{
  "query": "query { __typename }",
  "variables": {},
  "operationName": null
}

{
  "query": "query ActiveBasket($voucherCodes: [String!], $shippingCosts: MoneyTypeInput, $orderChannel: OrderChannel!, $customerId: String) {
  activeBasket {
    ... on ActiveBasketResult {
      basket {
        ...FullBasket
      }
    }
    ... on BasketError {
      errorMessage
      reason
    }
  }
}",
  "operationName": "ActiveBasket",
  "variables": {
    "voucherCodes": "<value>",
    "shippingCosts": "<value>",
    "orderChannel": "<value>",
    "customerId": "<value>"
  }
}

{
  "query": "mutation AddBasketItems($input: AddBasketLinesInput!, $voucherCodes: [String!], $shippingCosts: MoneyTypeInput, $orderChannel: OrderChannel!, $customerId: String) {\n  addBasketLines(input: $input) {\n    ... on Basket {\n      ...FullBasket\n    }\n    ... on Error {\n      ...Error\n    }\n  }\n}",
  "operationName": "AddBasketItems",
  "variables": {
    "input": "<value>",
    "voucherCodes": "<value>",
    "shippingCosts": "<value>",
    "orderChannel": "<value>",
    "customerId": "<value>"
